import json
from typing import Any

from lfx.custom import Component
from lfx.io import BoolInput, HandleInput, Output, TabInput
from lfx.schema import Data, DataFrame, Message

MIN_CSV_LINES = 2


def convert_to_message(v) -> Message:
    """Convert input to Message type.

    Args:
        v: Input to convert (Message, Data, DataFrame, or dict)

    Returns:
        Message: Converted Message object
    """
    return v if isinstance(v, Message) else v.to_message()


def convert_to_data(v: DataFrame | Data | Message | dict, *, auto_parse: bool) -> Data:
    """Convert input to Data type.

    Args:
        v: Input to convert (Message, Data, DataFrame, or dict)
        auto_parse: Enable automatic parsing of structured data (JSON/CSV)

    Returns:
        Data: Converted Data object
    """
    if isinstance(v, dict):
        return Data(v)
    if isinstance(v, Message):
        data = Data(data={"text": v.data["text"]})
        return parse_structured_data(data) if auto_parse else data

    if isinstance(v, DataFrame):
        # Keep source text when converting tabular file loader output into Data.
        # This avoids empty-document ingestion in downstream chunking/vector-store steps.
        try:
            rows = v.to_data_list()
        except Exception:  # noqa: BLE001
            return v.to_data()

        text_parts = []
        for row in rows:
            if isinstance(row, Data):
                row_text = (row.get_text() or "").strip()
                if not row_text:
                    payload = getattr(row, "data", {}) or {}
                    for key in ("text", "content", "page_content", "body"):
                        value = payload.get(key)
                        if isinstance(value, str) and value.strip():
                            row_text = value.strip()
                            break
                    if not row_text and payload:
                        row_text = "\n".join(
                            f"{k}: {v}"
                            for k, v in payload.items()
                            if v is not None and str(v).strip()
                        )
                if row_text:
                    text_parts.append(row_text)

        if text_parts:
            merged = "\n\n".join(text_parts)
            data = Data(data={"text": merged})
            return parse_structured_data(data) if auto_parse else data

        return v.to_data()

    return v if isinstance(v, Data) else v.to_data()


def convert_to_dataframe(v: DataFrame | Data | Message | dict, *, auto_parse: bool) -> DataFrame:
    """Convert input to DataFrame type.

    Args:
        v: Input to convert (Message, Data, DataFrame, or dict)
        auto_parse: Enable automatic parsing of structured data (JSON/CSV)

    Returns:
        DataFrame: Converted DataFrame object
    """
    import pandas as pd

    if isinstance(v, dict):
        return DataFrame([v])
    if isinstance(v, DataFrame):
        return v
    # Handle pandas DataFrame
    if isinstance(v, pd.DataFrame):
        # Convert pandas DataFrame to our DataFrame by creating Data objects
        return DataFrame(data=v)

    if isinstance(v, Message):
        data = Data(data={"text": v.data["text"]})
        return parse_structured_data(data).to_dataframe() if auto_parse else data.to_dataframe()
    # For other types, call to_dataframe method
    return v.to_dataframe()


def parse_structured_data(data: Data) -> Data:
    """Parse structured data (JSON, CSV) from Data's text field.

    Args:
        data: Data object with text content to parse

    Returns:
        Data: Modified Data object with parsed content or original if parsing fails
    """
    raw_text = data.get_text() or ""
    text = raw_text.lstrip("\ufeff").strip()

    # Try JSON parsing first
    parsed_json = _try_parse_json(text)
    if parsed_json is not None:
        return parsed_json

    # Try CSV parsing
    if _looks_like_csv(text):
        try:
            return _parse_csv_to_data(text)
        except Exception:  # noqa: BLE001
            # Heuristic misfire or malformed CSV — keep original data
            return data

    # Return original data if no parsing succeeded
    return data


def _try_parse_json(text: str) -> Data | None:
    """Try to parse text as JSON and return Data object."""
    try:
        parsed = json.loads(text)

        if isinstance(parsed, dict):
            # Single JSON object
            return Data(data=parsed)
        if isinstance(parsed, list) and all(isinstance(item, dict) for item in parsed):
            # Array of JSON objects - create Data with the list
            return Data(data={"records": parsed})

    except (json.JSONDecodeError, ValueError):
        pass

    return None


def _looks_like_csv(text: str) -> bool:
    """Simple heuristic to detect CSV content."""
    lines = text.strip().split("\n")
    if len(lines) < MIN_CSV_LINES:
        return False

    header_line = lines[0]
    return "," in header_line and len(lines) > 1


def _parse_csv_to_data(text: str) -> Data:
    """Parse CSV text and return Data object."""
    from io import StringIO

    import pandas as pd

    # Parse CSV to DataFrame, then convert to list of dicts
    parsed_df = pd.read_csv(StringIO(text))
    records = parsed_df.to_dict(orient="records")

    return Data(data={"records": records})


class TypeConverterComponent(Component):
    display_name = "Type Convert"
    description = "Convert between different types (Message, Data, DataFrame)"
    documentation: str = "https://docs.langflow.org/type-convert"
    icon = "repeat"

    inputs = [
        HandleInput(
            name="input_data",
            display_name="Input",
            input_types=["Message", "Data", "DataFrame"],
            info="Accept Message, Data or DataFrame as input",
            required=True,
        ),
        BoolInput(
            name="auto_parse",
            display_name="Auto Parse",
            info="Detect and convert JSON/CSV strings automatically.",
            advanced=True,
            value=False,
            required=False,
        ),
        TabInput(
            name="output_type",
            display_name="Output Type",
            options=["Message", "Data", "DataFrame"],
            info="Select the desired output data type",
            real_time_refresh=True,
            value="Message",
        ),
    ]

    outputs = [
        Output(
            display_name="Message Output",
            name="message_output",
            method="convert_to_message",
        )
    ]

    def update_outputs(self, frontend_node: dict, field_name: str, field_value: Any) -> dict:
        """Dynamically show only the relevant output based on the selected output type."""
        if field_name == "output_type":
            # Start with empty outputs
            frontend_node["outputs"] = []

            # Add only the selected output type
            if field_value == "Message":
                frontend_node["outputs"].append(
                    Output(
                        display_name="Message Output",
                        name="message_output",
                        method="convert_to_message",
                    ).to_dict()
                )
            elif field_value == "Data":
                frontend_node["outputs"].append(
                    Output(
                        display_name="Data Output",
                        name="data_output",
                        method="convert_to_data",
                    ).to_dict()
                )
            elif field_value == "DataFrame":
                frontend_node["outputs"].append(
                    Output(
                        display_name="DataFrame Output",
                        name="dataframe_output",
                        method="convert_to_dataframe",
                    ).to_dict()
                )

        return frontend_node

    def convert_to_message(self) -> Message:
        """Convert input to Message type."""
        input_value = self.input_data[0] if isinstance(self.input_data, list) else self.input_data

        # Handle string input by converting to Message first
        if isinstance(input_value, str):
            input_value = Message(text=input_value)

        result = convert_to_message(input_value)
        self.status = result
        return result

    def convert_to_data(self) -> Data:
        """Convert input to Data type."""
        input_value = self.input_data[0] if isinstance(self.input_data, list) else self.input_data

        # Handle string input by converting to Message first
        if isinstance(input_value, str):
            input_value = Message(text=input_value)

        result = convert_to_data(input_value, auto_parse=self.auto_parse)
        self.status = result
        return result

    def convert_to_dataframe(self) -> DataFrame:
        """Convert input to DataFrame type."""
        input_value = self.input_data[0] if isinstance(self.input_data, list) else self.input_data

        # Handle string input by converting to Message first
        if isinstance(input_value, str):
            input_value = Message(text=input_value)

        result = convert_to_dataframe(input_value, auto_parse=self.auto_parse)
        self.status = result
        return result

from lfx.custom.custom_component.component import Component
from lfx.io import HandleInput, IntInput, Output
from lfx.schema.data import Data
from lfx.schema.message import Message


class ContextMergeFormatter(Component):
    display_name = "Context Merge Formatter"
    description = "Merge retriever outputs from multiple branches into one clean message context."
    icon = "combine"
    name = "ContextMergeFormatter"

    inputs = [
        HandleInput(
            name="input_data",
            display_name="Retriever Results",
            input_types=["Message", "Data", "DataFrame"],
            required=True,
            list=True,
        ),
        IntInput(
            name="max_chunks",
            display_name="Max Chunks",
            value=6,
            info="Maximum number of chunks to include in the merged context.",
        ),
    ]

    outputs = [
        Output(
            display_name="Message Output",
            name="message_output",
            method="build_message",
        ),
    ]

    def _flatten_items(self, value):
        if value is None:
            return []
        items = value if isinstance(value, list) else [value]
        flattened = []
        for item in items:
            if item is None:
                continue
            if isinstance(item, list):
                flattened.extend(self._flatten_items(item))
            elif hasattr(item, "to_data_list"):
                try:
                    flattened.extend(item.to_data_list())
                except Exception:  # noqa: BLE001
                    flattened.append(item)
            else:
                flattened.append(item)
        return flattened

    def _stringify_metadata(self, payload):
        for key in ("source", "path", "file_path", "title", "document_name", "filename", "collection_name"):
            value = payload.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()
        return ""

    def _extract_text(self, item):
        if isinstance(item, Message):
            return (item.text or "").strip(), ""
        if isinstance(item, Data):
            payload = getattr(item, "data", {}) or {}
            text = (item.get_text() or "").strip()
            if not text:
                for key in ("text", "page_content", "content", "body", "chunk"):
                    value = payload.get(key)
                    if isinstance(value, str) and value.strip():
                        text = value.strip()
                        break
            if not text:
                text = "\n".join(
                    f"{key}: {value}"
                    for key, value in payload.items()
                    if value is not None and str(value).strip() and key not in {"id"}
                ).strip()
            return text, self._stringify_metadata(payload)
        if isinstance(item, dict):
            text = ""
            for key in ("text", "page_content", "content", "body", "chunk"):
                value = item.get(key)
                if isinstance(value, str) and value.strip():
                    text = value.strip()
                    break
            if not text:
                text = "\n".join(
                    f"{key}: {value}"
                    for key, value in item.items()
                    if value is not None and str(value).strip()
                ).strip()
            return text, self._stringify_metadata(item)
        text = str(item or "").strip()
        return text, ""

    def build_message(self) -> Message:
        items = self._flatten_items(self.input_data)
        chunks = []
        seen = set()
        limit = max(int(self.max_chunks or 6), 1)

        for item in items:
            text, label = self._extract_text(item)
            if not text:
                continue
            normalized = " ".join(text.split()).lower()
            if normalized in seen:
                continue
            seen.add(normalized)
            if label:
                chunks.append(f"[{label}]\n{text}")
            else:
                chunks.append(text)
            if len(chunks) >= limit:
                break

        if not chunks:
            message = Message(text="No retrieval context was returned by the selected branch.")
            self.status = message.text
            return message

        message = Message(text="\n\n---\n\n".join(chunks))
        self.status = message.text
        return message
